import { InsufficientStockError, ValidationError } from '../errors/DomainErrors';
import { Money } from '../shared/Money';
import { Quantity } from '../shared/Quantity';

export interface ProductSnapshot {
  readonly id: string;
  readonly name: string;
  readonly unitPriceCents: number;
  readonly onHand: number;
  readonly reserved: number;
}

export interface CreateProductProps {
  readonly id: string;
  readonly name: string;
  readonly unitPrice: Money;
  readonly initialStock: number;
}

/**
 * A catalogue product and its stock.
 * `onHand` is physically in the warehouse; `reserved` is promised to open orders.
 */
export class Product {
  private constructor(
    readonly id: string,
    readonly name: string,
    readonly unitPrice: Money,
    private onHandUnits: number,
    private reservedUnits: number,
  ) {}

  static create(props: CreateProductProps): Product {
    if (props.name.trim() === '') {
      throw new ValidationError('A product requires a name');
    }
    if (!Number.isInteger(props.initialStock) || props.initialStock < 0) {
      throw new ValidationError('Initial stock must be a non-negative integer');
    }
    return new Product(props.id, props.name, props.unitPrice, props.initialStock, 0);
  }

  static restore(snapshot: ProductSnapshot): Product {
    return new Product(
      snapshot.id,
      snapshot.name,
      Money.ofCents(snapshot.unitPriceCents),
      snapshot.onHand,
      snapshot.reserved,
    );
  }

  get onHand(): number {
    return this.onHandUnits;
  }

  get reserved(): number {
    return this.reservedUnits;
  }

  get available(): number {
    return this.onHandUnits - this.reservedUnits;
  }

  canReserve(quantity: Quantity): boolean {
    return quantity.value <= this.available;
  }

  reserve(quantity: Quantity): void {
    if (!this.canReserve(quantity)) {
      throw new InsufficientStockError(this.id, quantity.value, this.available);
    }
    this.reservedUnits += quantity.value;
  }

  release(quantity: Quantity): void {
    this.assertReserved(quantity);
    this.reservedUnits -= quantity.value;
  }

  /** Turns a reservation into an actual stock movement when goods leave the warehouse. */
  commit(quantity: Quantity): void {
    this.assertReserved(quantity);
    this.reservedUnits -= quantity.value;
    this.onHandUnits -= quantity.value;
  }

  toSnapshot(): ProductSnapshot {
    return {
      id: this.id,
      name: this.name,
      unitPriceCents: this.unitPrice.cents,
      onHand: this.onHandUnits,
      reserved: this.reservedUnits,
    };
  }

  private assertReserved(quantity: Quantity): void {
    if (quantity.value > this.reservedUnits) {
      throw new ValidationError(
        `Product '${this.id}' has only ${this.reservedUnits} reserved units, cannot settle ${quantity.value}`,
      );
    }
  }
}

